    """백트래킹 알고리즘: 부분 집합 합 II"""
    # 부분 집합의 합이 target과 같으면 해를 기록한다
    if target == 0:
        res.append(list(state))
        return
    # 모든 선택지를 순회한다
    # 가지치기 2: start부터 순회하여 중복 부분 집합 생성을 방지한다
    # 가지치기 3: start부터 순회하여 같은 원소의 중복 선택을 방지한다
    for i in range(start, len(choices)):
