    break if target - choices[i] &lt; 0
    # 가지치기 4: 해당 원소가 왼쪽 원소와 같으면 탐색 분기가 중복되므로 바로 건너뛴다
    next if i &gt; start &amp;&amp; choices[i] == choices[i - 1]
    # 시도: 선택하고 target, start를 갱신한다
    state &lt;&lt; choices[i]
    # 다음 선택을 진행한다
