                dp[i][a] = dp[i - 1][a];
            } else {
                // 동전 i를 선택하지 않는 경우와 선택하는 경우의 방법 수를 더한다
                dp[i][a] = dp[i - 1][a] + dp[i][a - coins[i - 1]];
            }
        }
    }
    int res = dp[n][amt];
    // 메모리 해제
    for (int i = 0; i &lt;= n; i++) {
        free(dp[i]);
    }
    free(dp);
    return res;
}
